```javascript
// 1. 手动创建私有消息总线（重复调用无副作用）
eda.sys_MessageBus.createPrivateMessageBus();

// 2. 订阅一个主题，验证总线已就绪
const task = eda.sys_MessageBus.subscribe('嘉立创示例_创建总线', (message) => {
  console.log('订阅者收到：', message);
});

// 3. 发布消息，回调立即触发
eda.sys_MessageBus.publish('嘉立创示例_创建总线', '总线已创建并可用');

// 4. 取消订阅，恢复原状
task.cancel();
console.log('已取消订阅');
```
